// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "../bridge";

export interface LoginIn {
  username: string;
  password: string;
  /** Optional terminal name shown in session lists */
  terminal_label?: string | null;
}

export interface LoginOut {
  access_token: string;
  /** Always bearer */
  token_type: string;
  /** Access token lifetime in seconds */
  expires_in: number;
  refresh_token: string;
  refresh_expires_in: number;
  user: MeOut;
  /** Show `message` as a banner while `state` is grace or locked */
  license: LicenseStatusOut;
}

export interface MeOut {
  user_id: number;
  username: string;
  display_name: string;
  /** Null for accounts without an employee (e.g. the bootstrap Super Admin) */
  employee_id: number | null;
  emp_number: string | null;
  designation: string | null;
  department: string | null;
  roles: string[];
  permissions: string[];
  workspaces: WorkspaceOut[];
  must_change_password: boolean;
  preferences: PreferencesOut;
}

export interface WorkspaceOut {
  code: string;
  label: string;
  label_ur: string;
  description: string;
  /** The user's roles that open this workspace (empty for My Workspace when no role lands there: every employee has it) */
  roles: string[];
  /** True for My Workspace (self_service): every user with an employee record has it, whatever their roles. Open it like any workspace (its window sends X-Active-Workspace: self_service), but do not count it for the launcher: a user with one role workspace opens that one directly and reaches My Workspace from the user's menu */
  every_employee: boolean;
}

/** Display preferences and the user's own UI state (`preferences.extra`). */
export interface PreferencesOut {
  theme: "Light" | "DarkHighContrast";
  language: "en" | "ur";
  ui_scale_pct: number;
  /** Separate (a download button per document) or Combined (one PDF) for a set of documents */
  pdf_download: "Separate" | "Combined";
  /** The user's own UI state (PUT /settings/me extra), as saved */
  extra: Record<string, unknown>;
}

/** The server's license state (licensing.public_view): no hardware details. */
export interface LicenseStatusOut {
  state: "ok" | "grace" | "locked" | "dev";
  reason: "hardware_changed" | "license_missing" | "license_invalid" | "license_outdated" | "license_expired" | "hardware_unreadable" | "check_failed" | "standby_main_active" | "standby_check_failed" | "standby_invalid" | null;
  /** One sentence for people: show it as the banner */
  message: string;
  hospital: string | null;
  license_id: string | null;
  grace_until: string | null;
  days_left: number | null;
  expires_at: string | null;
  /** A milder warning (e.g. the license ends within 30 days), even when ok */
  notice: string | null;
  vendor: VendorContactOut;
  logins: "all" | "super_admin_only";
}

/** The vendor to contact about the license (only the channels the vendor gave are present). */
export interface VendorContactOut {
  company: string;
  phone?: string | null;
  whatsapp?: string | null;
  email?: string | null;
  website?: string | null;
}

/** This terminal's location, printers and cash node. The location and printer fields are present only when `registered` is true; `hint` only when it is false. */
export interface TerminalIdentityOut {
  registered: boolean;
  client_ip: string | null;
  mac: string | null;
  hint?: string | null;
  location_label?: string | null;
  cash_node?: "MainReception" | "PharmacyCounter" | "LabReception" | "IPDBilling" | "EmergencyCounter" | "CashierDesk" | null;
  ip?: string | null;
  receipt_printer?: string | null;
  receipt_printer_address?: string | null;
  receipt_paper_mm?: number | null;
  label_printer?: string | null;
  label_printer_address?: string | null;
  document_printer?: string | null;
  document_printer_address?: string | null;
  card_printer?: string | null;
  card_printer_address?: string | null;
}

export interface ChangePasswordIn {
  current_password: string;
  new_password: string;
}

export interface TokenPair {
  access_token: string;
  /** Always bearer */
  token_type: string;
  /** Access token lifetime in seconds */
  expires_in: number;
  refresh_token: string;
  refresh_expires_in: number;
}

/** GET /health/live: the server answers (no database is touched). */
export interface LiveOut {
  status: "alive";
}

/** GET /health: the login screen's connection check and the Settings window's This terminal section. */
export interface HealthOut {
  /** degraded, answered with HTTP 503: the database is down */
  status: "ok" | "degraded";
  version: string;
  server_time: string;
  components: HealthComponentsOut;
  maintenance_mode: boolean;
  /** While maintenance_mode: the message for the maintenance screen, to show word for word. IT's own (written in the Control Center or PUT /admin/maintenance), else the server's default: the same text as the MAINTENANCE error's message. null otherwise */
  maintenance_message: string | null;
  license: HealthLicenseOut;
  uptime_seconds: number;
}

export interface HealthComponentsOut {
  database: "up" | "down";
  /** The database listener behind the WebSocket events */
  realtime: "up" | "down";
}

/** The license summary of GET /health (GET /meta/license has the whole state, the vendor's contact included). */
export interface HealthLicenseOut {
  state: "ok" | "grace" | "locked" | "dev";
  /** Empty when there is nothing to report */
  reason: "" | "hardware_changed" | "license_missing" | "license_invalid" | "license_outdated" | "license_expired" | "hardware_unreadable" | "check_failed" | "standby_main_active" | "standby_check_failed" | "standby_invalid";
  /** One sentence for people */
  detail: string;
  grace_until: string | null;
  days_left: number | null;
}

/** Log in (returns tokens, profile, roles, workspaces) — POST /api/v1/auth/login (who may call: public: no login (works before login)). */
export function login(body: LoginIn): Promise<LoginOut> {
  return api<LoginOut>("POST", `/auth/login`, body);
}

/** Identify this terminal (location + mapped printers) — works before login — GET /api/v1/terminals/whoami (who may call: public: no login (works before login)). */
export function whoami(): Promise<TerminalIdentityOut> {
  return api<TerminalIdentityOut>("GET", `/terminals/whoami`, undefined);
}

/** Change own password — POST /api/v1/auth/change-password (who may call: any logged-in user, for their own account (also before a forced password change where allowed)). */
export function changePasswordAuth(body: ChangePasswordIn): Promise<TokenPair> {
  return api<TokenPair>("POST", `/auth/change-password`, body);
}

/** The server's license state: show a banner when it needs attention — works before login — GET /api/v1/meta/license (who may call: public: no login (works before login)). */
export function licenseStatus(): Promise<LicenseStatusOut> {
  return api<LicenseStatusOut>("GET", `/meta/license`, undefined);
}

/** Is the server there? (unauthenticated, no database) — GET /health/live (who may call: public: no login (works before login)). */
export function liveHealthLiveGet(): Promise<LiveOut> {
  return api<LiveOut>("GET", `/health/live`, undefined);
}

/** Server health (unauthenticated; used by the login screen) — GET /health (who may call: public: no login (works before login)). */
export function healthHealthGet(): Promise<HealthOut> {
  return api<HealthOut>("GET", `/health`, undefined);
}
